package com.weddingplanner.controller;

import com.weddingplanner.entity.Wedding;
import com.weddingplanner.repository.WeddingRepository;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.web.bind.annotation.*;

import java.util.List;

@RestController
@RequestMapping("/api/weddings")
@CrossOrigin(origins = "*")
public class WeddingController {

    @Autowired
    private WeddingRepository weddingRepository;

    @GetMapping
    public List<Wedding> getAllWeddings() {
        return weddingRepository.findAll();
    }

    @PostMapping
    public Wedding createWedding(@RequestBody Wedding wedding) {
        wedding.setStatus("planned");
        return weddingRepository.save(wedding);
    }

    @GetMapping("/{id}")
    public Wedding getWeddingById(@PathVariable Long id) {
        return weddingRepository.findById(id).orElseThrow();
    }
}

package com.weddingplanner.entity;

import jakarta.persistence.*;
import lombok.Data;
import java.math.BigDecimal;

@Entity
@Data
@Table(name = "budgets")
public class Budget {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @ManyToOne
    @JoinColumn(name = "wedding_id")
    private Wedding wedding;

    private String category; // venue, photography, catering, etc.
    private BigDecimal allocatedAmount;
    private BigDecimal spentAmount;
    private BigDecimal remainingAmount;

}

package com.weddingplanner.entity;

import jakarta.persistence.*;
import lombok.Data;
import java.math.BigDecimal;
import java.time.LocalDateTime;

@Entity
@Data
@Table(name = "payments")
public class Payment {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @ManyToOne
    @JoinColumn(name = "wedding_id")
    private Wedding wedding;

    private BigDecimal amount;
    private String type; // deposit, full payment, vendor payment
    private String status; // pending, completed, failed
    private LocalDateTime paymentDate;
    private String paymentMethod; // credit card, bank transfer, etc.
    private String transactionId;

}

package com.weddingplanner.entity;

import jakarta.persistence.*;
import lombok.Data;
import java.time.LocalDate;
import java.util.List;

@Entity
@Data
@Table(name = "weddings")
public class Wedding {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    private String partner1Name;
    private String partner2Name;
    private LocalDate weddingDate;
    private Integer guestCount;
    private String packageType;
    private String status; // planned, confirmed, completed

    @OneToMany(mappedBy = "wedding", cascade = CascadeType.ALL)
    private List<Budget> budgets;

    @OneToMany(mappedBy = "wedding", cascade = CascadeType.ALL)
    private List<Payment> payments;

}

